            displayedPages: 3,
            prevText: 'Prev'.translate(),
            nextText: 'Next'.translate(),
            invertPageOrder: false,
            labelMap: [],
            hrefTextPrefix: '#page-',
            hrefTextSuffix: '',
            nextAtFront: false,
            edges: 2,
            useStartEdge: true,
            ellipseText: '&hellip;',
            selectOnClick: true,
            useEndEdge: true,
            pageSize: 0,
            filterable: true,
            inititalPage: 0,
            customStatusBar: null,
            rowStyle: null,
            visibleHeaders: true,
            filterPlaceholder: "",
            onRowClick: null,
            sortableItems: '> tr:not(.pmui-nodrag)',
